def _is_admin():
    try:
        import ctypes
        return ctypes.windll.shell32.IsUserAnAdmin() != 0
    except Exception:
        return False

# Sentinel passed to the elevated relaunch so we NEVER relaunch more than once
# (prevents an infinite spawn loop if elevation can't be detected afterwards).
_ELEVATED_FLAG = "--pcmon-elevated"

def _relaunch_as_admin():
    """Relaunch the current process elevated via UAC. Returns True if a relaunch
    was triggered (caller should exit), False if already admin or relaunch failed."""
    if _is_admin():
        return False
    try:
        import ctypes
        # Forward existing args (minus our own sentinel) plus the sentinel.
        fwd = [a for a in _sys.argv[1:] if a != _ELEVATED_FLAG]
        if getattr(_sys, 'frozen', False):
            # Standalone EXE: re-run the EXE itself
            exe = _sys.executable
            params = subprocess.list2cmdline(fwd + [_ELEVATED_FLAG])
        else:
            # Script: re-run with pythonw.exe (no console window) when available
            exe = _sys.executable
            pyw = os.path.join(os.path.dirname(exe), "pythonw.exe")
            if os.path.isfile(pyw):
                exe = pyw
            params = subprocess.list2cmdline(
                [os.path.abspath(__file__)] + fwd + [_ELEVATED_FLAG])
        # ShellExecuteW with "runas" triggers the UAC elevation prompt.
        # Returns >32 on success.
        rc = ctypes.windll.shell32.ShellExecuteW(
            None, "runas", exe, params, _APP_DIR, 1)
        return rc > 32
    except Exception:
        return False

# ── Start-on-boot via a logon Scheduled Task ─────────────────────────────────
# A scheduled task (rather than an HKCU\...\Run entry) is used on purpose: this
# app self-elevates via UAC, so a plain Run entry would pop a UAC prompt at
# every login. A task created with "Run with highest privileges" launches the
# app already-elevated and silently, so there's no prompt on boot.
_STARTUP_TASK_NAME = "RozakosPCMonitorSender"
# Flag forwarded by the boot launch so the app goes straight to the tray.
_MINIMIZED_FLAG = "--start-minimized"

def _startup_launch_cmd():
    """The command line the logon task should run (elevated + minimized)."""
    if getattr(_sys, 'frozen', False):
        exe = _sys.executable
        return f'"{exe}" {_ELEVATED_FLAG} {_MINIMIZED_FLAG}'
    exe = _sys.executable
    pyw = os.path.join(os.path.dirname(exe), "pythonw.exe")
    if os.path.isfile(pyw):
        exe = pyw
    return f'"{exe}" "{os.path.abspath(__file__)}" {_ELEVATED_FLAG} {_MINIMIZED_FLAG}'

def _startup_enabled():
    """True if the logon scheduled task already exists."""
    try:
        r = subprocess.run(
            ["schtasks", "/Query", "/TN", _STARTUP_TASK_NAME],
            capture_output=True, text=True, creationflags=_NO_WINDOW)
        return r.returncode == 0
    except Exception:
        return False

def _enable_startup():
    """Create the logon task. Returns (ok, message)."""
    try:
        r = subprocess.run(
            ["schtasks", "/Create", "/TN", _STARTUP_TASK_NAME,
             "/TR", _startup_launch_cmd(), "/SC", "ONLOGON",
             "/RL", "HIGHEST", "/F"],
            capture_output=True, text=True, creationflags=_NO_WINDOW)
        if r.returncode == 0:
            return True, "[OK]   Start-on-boot enabled (launches minimized to tray)."
        err = (r.stderr or r.stdout).strip()
        return False, f"[WARN] Could not enable start-on-boot: {err}"
    except Exception as e:
        return False, f"[WARN] Could not enable start-on-boot: {e}"

def _disable_startup():
    """Remove the logon task. Returns (ok, message)."""
    try:
        r = subprocess.run(
            ["schtasks", "/Delete", "/TN", _STARTUP_TASK_NAME, "/F"],
            capture_output=True, text=True, creationflags=_NO_WINDOW)
        if r.returncode == 0:
            return True, "[OK]   Start-on-boot disabled."
        err = (r.stderr or r.stdout).strip()
        return False, f"[WARN] Could not disable start-on-boot: {err}"
    except Exception as e:
        return False, f"[WARN] Could not disable start-on-boot: {e}"

# ── Settings persistence ─────────────────────────────────────────────────────
# Stored in the user profile (not _APP_DIR) so it works no matter where the EXE
# lives and whether the app is running elevated.
_SETTINGS_PATH = os.path.join(os.path.expanduser("~"), ".pcmonitor_sender.json")

def load_settings():
    """Read the saved settings dict; return {} if none / unreadable."""
    try:
        with open(_SETTINGS_PATH, "r", encoding="utf-8") as f:
            d = _json.load(f)
            return d if isinstance(d, dict) else {}
    except Exception:
        return {}

def save_settings(d):
    """Persist the settings dict atomically. Returns True on success.

    Writes to a temp file then os.replace()s it into place, so a crash or power
    loss mid-write can never leave a half-written (corrupt) settings file.
    """
    try:
        tmp = _SETTINGS_PATH + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            _json.dump(d, f, indent=2)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, _SETTINGS_PATH)
        return True
    except Exception:
        return False

def _ensure_lhm_deps(dll_path, log_fn=print):
    """Auto-install pythonnet and auto-download LHM DLL if needed."""

    # ── Step 1: ensure pythonnet ──────────────────────────────────────────
    try:
        import clr  # noqa: F401
        log_fn("[INFO] pythonnet already installed")
    except ImportError:
        log_fn("[INFO] pythonnet not found -- installing via pip...")
        try:
            import subprocess as _sp
            result = _sp.run(
                [_sys.executable, "-m", "pip", "install", "pythonnet"],
                capture_output=True, text=True, timeout=120,
                creationflags=_NO_WINDOW)
            if result.returncode == 0:
                log_fn("[OK]   pythonnet installed successfully")
            else:
                log_fn(f"[WARN] pip install pythonnet failed: {result.stderr.strip()}")
                return dll_path
        except Exception as e:
            log_fn(f"[WARN] Could not install pythonnet: {e}")
            return dll_path

    # ── Step 1b: ensure .NET 9 Desktop Runtime ────────────────────────────
    try:
        result = subprocess.run(
            ["dotnet", "--list-runtimes"],
            capture_output=True, text=True, timeout=10,
            creationflags=_NO_WINDOW)
        runtimes = result.stdout if result.returncode == 0 else ""
        has_net9 = any("Microsoft.WindowsDesktop.App 9." in line for line in runtimes.splitlines())

        if has_net9:
            log_fn("[INFO] .NET 9 Desktop Runtime found")
        else:
            desktop_rts = [l.strip() for l in runtimes.splitlines() if "WindowsDesktop" in l]
            if desktop_rts:
                log_fn(f"[INFO] Installed runtimes: {'; '.join(desktop_rts)}")
            log_fn("[INFO] .NET 9 Desktop Runtime not found -- installing via winget...")
            res = subprocess.run(
                ["winget", "install", "Microsoft.DotNet.DesktopRuntime.9",
                 "--accept-source-agreements", "--accept-package-agreements"],
                capture_output=True, text=True, timeout=300,
                creationflags=_NO_WINDOW)
            if res.returncode == 0:
                log_fn("[OK]   .NET 9 Desktop Runtime installed successfully")
                log_fn("[INFO] Restart the app for .NET 9 to take effect.")
            else:
                log_fn(f"[WARN] winget failed: {res.stderr.strip()[:120]}")
                log_fn("[INFO] Trying PowerShell dotnet-install script...")
                ps_cmd = (
                    'powershell -NoProfile -ExecutionPolicy Bypass -Command "'
                    '[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12; '
                    "Invoke-WebRequest 'https://dot.net/v1/dotnet-install.ps1' -OutFile dotnet-install.ps1; "
                    ".\\dotnet-install.ps1 -Runtime windowsdesktop -Channel 9.0 "
                    "-InstallDir 'C:\\Program Files\\dotnet'" + '"'
                )
                res2 = subprocess.run(ps_cmd, shell=True, capture_output=True, text=True, timeout=300,
                                      creationflags=_NO_WINDOW)
                if res2.returncode == 0:
                    log_fn("[OK]   .NET 9 Desktop Runtime installed via PowerShell")
                    log_fn("[INFO] Restart the app for .NET 9 to take effect.")
                else:
                    log_fn("[WARN] Auto-install failed. Please install manually:")
                    log_fn("[WARN] https://dotnet.microsoft.com/download/dotnet/9.0")
                    log_fn("[WARN] Download '.NET Desktop Runtime 9.0' (x64 installer)")
    except FileNotFoundError:
        log_fn("[WARN] 'dotnet' not found -- please install .NET 9 Desktop Runtime:")
        log_fn("[WARN] https://dotnet.microsoft.com/download/dotnet/9.0")
    except Exception as e:
        log_fn(f"[WARN] .NET runtime check failed: {e}")

    # ── Step 1c: download LHM from NuGet (v0.9.4, netstandard2.0) ────────
    # GitHub v0.9.6 targets .NET 10 preview; NuGet v0.9.4 works with .NET 8/9
    _NUGET_LHM_PKG = "LibreHardwareMonitorLib"
    _NUGET_LHM_VER = "0.9.4"
    _NUGET_DEPS = [
        ("System.Threading.AccessControl", "8.0.0"),
        ("System.IO.FileSystem.AccessControl", "5.0.0"),
        ("System.Security.AccessControl", "6.0.1"),
        ("System.Security.Principal.Windows", "5.0.0"),
    ]
    nuget_dir = os.path.join(
        os.path.dirname(dll_path) or _LHM_DIR,
        "nuget")
    nuget_dll = os.path.join(nuget_dir, "LibreHardwareMonitorLib.dll")

    def _download_nupkg(pkg_name, pkg_ver, dest_dir, log_fn):
        """Download a NuGet package and extract DLLs from it."""
        import ssl
        ctx = ssl.create_default_context()
        url = (f"https://api.nuget.org/v3-flatcontainer/"
               f"{pkg_name.lower()}/{pkg_ver}/{pkg_name.lower()}.{pkg_ver}.nupkg")
        req = urllib.request.Request(url, headers={"User-Agent": "PCMonitorGUI/1.0"})
        with urllib.request.urlopen(req, context=ctx, timeout=30) as resp:
            data = resp.read()
        os.makedirs(dest_dir, exist_ok=True)
        extracted = []
        with zipfile.ZipFile(io.BytesIO(data)) as zf:
            for preferred in ["lib/net8.0/", "lib/net6.0/", "lib/netstandard2.0/", "lib/"]:
                for m in zf.namelist():
                    if m.lower().startswith(preferred.lower()) and m.lower().endswith(".dll"):
                        fname = os.path.basename(m)
                        out = os.path.join(dest_dir, fname)
                        with open(out, "wb") as f:
                            f.write(zf.read(m))
                        extracted.append(fname)
                if extracted:
                    break
            if not extracted:
                # Fallback: any DLL matching the package name
                for m in zf.namelist():
                    if m.lower().endswith(f"{pkg_name.lower()}.dll"):
                        fname = os.path.basename(m)
                        out = os.path.join(dest_dir, fname)
                        with open(out, "wb") as f:
                            f.write(zf.read(m))
                        extracted.append(fname)
                        break
        return extracted

    # Download LHM NuGet package if not present
    if not os.path.isfile(nuget_dll):
        log_fn(f"[INFO] Downloading NuGet: {_NUGET_LHM_PKG} v{_NUGET_LHM_VER}...")
        try:
            files = _download_nupkg(_NUGET_LHM_PKG, _NUGET_LHM_VER, nuget_dir, log_fn)
            if files:
                log_fn(f"[OK]   NuGet LHM extracted: {', '.join(files)}")
            else:
                log_fn("[WARN] No DLLs found in NuGet package")
        except Exception as e:
            log_fn(f"[WARN] NuGet LHM download failed: {e}")

    # Download dependency DLLs
    for pkg_name, pkg_ver in _NUGET_DEPS:
        dep_dll = os.path.join(nuget_dir, f"{pkg_name}.dll")
        if os.path.isfile(dep_dll):
            continue
        log_fn(f"[INFO] Downloading NuGet dep: {pkg_name} v{pkg_ver}...")
        try:
            files = _download_nupkg(pkg_name, pkg_ver, nuget_dir, log_fn)
            if files:
                log_fn(f"[OK]   Extracted {', '.join(files)}")
            else:
                log_fn(f"[WARN] {pkg_name}.dll not found in NuGet package")
        except Exception as e:
            log_fn(f"[WARN] NuGet download failed for {pkg_name}: {e}")

    # ── Step 2: ensure DLL exists ─────────────────────────────────────────
    if os.path.isfile(dll_path):
        return dll_path

    dll_dir = os.path.dirname(dll_path) or _LHM_DIR
    dll_name = "LibreHardwareMonitorLib.dll"
    target = os.path.join(dll_dir, dll_name)

    log_fn(f"[INFO] LHM DLL not found at: {dll_path}")
    log_fn("[INFO] Auto-downloading LibreHardwareMonitor from GitHub...")

    try:
        import ssl
        import json as _json

        ctx = ssl.create_default_context()
        api_url = "https://api.github.com/repos/LibreHardwareMonitor/LibreHardwareMonitor/releases/latest"
        req = urllib.request.Request(api_url, headers={"User-Agent": "PCMonitorGUI/1.0"})
        with urllib.request.urlopen(req, context=ctx, timeout=15) as resp:
            release = _json.loads(resp.read().decode())

        tag = release.get("tag_name", "?")
        zip_url = None
        for a in release.get("assets", []):
            name = a.get("name", "").lower()
            if name.endswith(".zip") and "libre" in name:
                zip_url = a["browser_download_url"]; break
        if not zip_url:
            for a in release.get("assets", []):
                if a.get("name", "").lower().endswith(".zip"):
                    zip_url = a["browser_download_url"]; break

        if not zip_url:
            log_fn(f"[WARN] No zip asset found in release {tag}")
            return dll_path

        log_fn(f"[INFO] Downloading {tag}...")
        req2 = urllib.request.Request(zip_url, headers={"User-Agent": "PCMonitorGUI/1.0"})
        with urllib.request.urlopen(req2, context=ctx, timeout=120) as resp:
            data = resp.read()
        log_fn(f"[INFO] Downloaded {len(data)//1024} KB -- extracting DLL...")

        os.makedirs(dll_dir, exist_ok=True)
        buf = io.BytesIO(data)
        found = False
        with zipfile.ZipFile(buf) as zf:
            for member in zf.namelist():
                if member.lower().endswith(dll_name.lower()):
                    with open(target, "wb") as fout:
                        fout.write(zf.read(member))
                    found = True
                    log_fn(f"[OK]   Extracted {dll_name} to {dll_dir}")
                    break
                # Also extract HidSharp.dll if present (needed by some LHM versions)
            for member in zf.namelist():
                bname = os.path.basename(member).lower()
                if bname.endswith(".dll") and bname != dll_name.lower():
                    dep_path = os.path.join(dll_dir, os.path.basename(member))
                    if not os.path.isfile(dep_path):
                        with open(dep_path, "wb") as fout:
                            fout.write(zf.read(member))

        if not found:
            log_fn("[WARN] DLL not found in zip archive")
            return dll_path

        return target

    except Exception as e:
        log_fn(f"[WARN] Auto-download failed: {e}")
        return dll_path


def _init_lhm(dll_path, log_fn=print):
    global _lhm_computer, _lhm_available, _lhm_init_tried
    _lhm_init_tried = True

    # Prefer NuGet v0.9.4 subfolder over GitHub v0.9.6
    dll_dir_base = os.path.dirname(os.path.abspath(dll_path))
    nuget_dir = os.path.join(dll_dir_base, "nuget")
    nuget_dll = os.path.join(nuget_dir, "LibreHardwareMonitorLib.dll")

    if os.path.isfile(nuget_dll):
        use_dir = nuget_dir
        use_dll = nuget_dll
        log_fn("[TEMP] Using NuGet LHM v0.9.4 (recommended)")
    elif os.path.isfile(dll_path):
        use_dir = dll_dir_base
        use_dll = os.path.abspath(dll_path)
        log_fn("[TEMP] Using GitHub LHM (NuGet not available)")
    else:
        log_fn(f"[TEMP] DLL not found: {dll_path}"); return False

    if not _is_admin():
        log_fn("[TEMP] WARNING: Not running as Administrator!")
        log_fn("[TEMP] LHM requires admin rights to read hardware sensors.")
        log_fn("[TEMP] Right-click the script/EXE and choose 'Run as administrator'.")
        log_fn("[TEMP] Temperatures will show N/A until relaunched as admin.")
    try:
        import sys as _sys
        import clr

        dll_name = os.path.splitext(os.path.basename(use_dll))[0]

        log_fn(f"[TEMP] pythonnet runtime: {_pn_runtime}")
        log_fn(f"[TEMP] DLL dir: {use_dir}")
        # List DLL files in the folder for diagnostics
        try:
            dlls_in_dir = [f for f in os.listdir(use_dir) if f.lower().endswith('.dll')]
            log_fn(f"[TEMP] DLLs in folder: {', '.join(sorted(dlls_in_dir))}")
        except Exception:
            pass

        # Ensure DLL directory is on sys.path
        if use_dir not in _sys.path:
            _sys.path.insert(0, use_dir)

        # Pre-load dependency DLLs (critical for NuGet approach)
        _DEP_NAMES = [
            "System.Security.Principal.Windows",
            "System.Security.AccessControl",
            "System.Threading.AccessControl",
            "System.IO.FileSystem.AccessControl",
        ]
        for dep_name in _DEP_NAMES:
            dep_path = os.path.join(use_dir, f"{dep_name}.dll")
            if os.path.isfile(dep_path):
                try:
                    clr.AddReference(dep_path)
                    log_fn(f"[TEMP] Pre-loaded: {dep_name}")
                except Exception:
                    pass  # May already be loaded or not needed

        # Load main LHM DLL
        loaded = False
        try:
            clr.AddReference(dll_name)
            loaded = True
            log_fn(f"[TEMP] Loaded via clr.AddReference(name)")
        except Exception as e1:
            log_fn(f"[TEMP] AddReference(name) failed: {e1}")

        if not loaded:
            try:
                clr.AddReference(use_dll)
                loaded = True
                log_fn(f"[TEMP] Loaded via clr.AddReference(full_path)")
            except Exception as e2:
                log_fn(f"[TEMP] AddReference(full_path) failed: {e2}")

        if not loaded:
            try:
                from System.Reflection import Assembly
                Assembly.LoadFile(use_dll)
                loaded = True
                log_fn("[TEMP] Loaded via Assembly.LoadFile()")
            except Exception as e3:
                log_fn(f"[TEMP] Assembly.LoadFile() failed: {e3}")

        if not loaded:
            log_fn("[TEMP] All DLL loading strategies failed!")
            return False

        try:
            from LibreHardwareMonitor.Hardware import Computer
        except ImportError as ie:
            log_fn(f"[TEMP] Import failed after load: {ie}")
            log_fn("[TEMP] The DLL loaded but types could not be resolved.")
            log_fn("[TEMP] Try deleting the LibreHardwareMonitor folder and restarting.")
            return False
        comp = Computer()
        comp.IsCpuEnabled    = True
        comp.IsGpuEnabled    = True
        comp.IsMemoryEnabled = True
        comp.Open()

        # Enumerate all hardware & sensors for diagnostics
        log_fn("[TEMP] === LHM Hardware & Sensors ===")
        hw_count = 0
        for hw in comp.Hardware:
            hw.Update()
            hw_count += 1
            log_fn(f"[TEMP]  HW: {hw.Name}  Type={hw.HardwareType}")
            sensor_count = 0
            for s in hw.Sensors:
                sensor_count += 1
                val_str = f"{s.Value:.1f}" if s.Value is not None else "None"
                log_fn(f"[TEMP]    Sensor: {s.Name}  Type={s.SensorType}  Value={val_str}")
            if sensor_count == 0:
                log_fn(f"[TEMP]    (no sensors found for this hardware)")
            # Also check sub-hardware (some CPUs have sub-devices)
            for sub in hw.SubHardware:
                sub.Update()
                log_fn(f"[TEMP]  SubHW: {sub.Name}  Type={sub.HardwareType}")
                for s in sub.Sensors:
                    val_str = f"{s.Value:.1f}" if s.Value is not None else "None"
                    log_fn(f"[TEMP]    Sensor: {s.Name}  Type={s.SensorType}  Value={val_str}")
        log_fn(f"[TEMP] === Total hardware items: {hw_count} ===")

        if hw_count == 0:
            log_fn("[TEMP] WARNING: LHM found no hardware! Sensors will not work.")

        _lhm_computer = comp; _lhm_available = True
        log_fn("[TEMP] LibreHardwareMonitor initialised OK"); return True
    except Exception as e:
        err_str = str(e)
        log_fn(f"[TEMP] LHM init failed: {err_str}")
        if "could not load file or assembly" in err_str.lower() or "could not load type" in err_str.lower():
            log_fn("[TEMP] Missing .NET dependency DLLs.")
            log_fn("[TEMP] Try deleting the LibreHardwareMonitor folder and restarting.")
        elif "not running as admin" in err_str.lower() or "access" in err_str.lower():
            log_fn("[TEMP] Run as Administrator to access hardware sensors.")
        else:
            log_fn("[TEMP] Ensure pythonnet is installed: pip install pythonnet")
        return False

_temp_debug_done = False

def get_cpu_temp():
    global _temp_debug_done
    if not _lhm_available or _lhm_computer is None: return -1.0
    try:
        from LibreHardwareMonitor.Hardware import HardwareType, SensorType
        for hw in _lhm_computer.Hardware:
            if hw.HardwareType == HardwareType.Cpu:
                hw.Update(); best = None
                if not _temp_debug_done:
                    print(f"[TEMP DBG] CPU hw found: {hw.Name} type={hw.HardwareType}")
                    for s in hw.Sensors:
                        val_s = f"{s.Value:.1f}" if s.Value is not None else "None"
                        print(f"[TEMP DBG]   {s.Name} type={s.SensorType} val={val_s}")
                    for sub in hw.SubHardware:
                        sub.Update()
                        print(f"[TEMP DBG]   SubHW: {sub.Name}")
                        for s in sub.Sensors:
                            val_s = f"{s.Value:.1f}" if s.Value is not None else "None"
                            print(f"[TEMP DBG]     {s.Name} type={s.SensorType} val={val_s}")
                for s in hw.Sensors:
                    if s.SensorType == SensorType.Temperature and s.Value is not None:
                        n = s.Name.lower()
                        if "package" in n or "tctl" in n or "tdie" in n: return float(s.Value)
                        if best is None: best = float(s.Value)
                if best is not None: return best
                # Check sub-hardware too (some Intel CPUs)
                for sub in hw.SubHardware:
                    sub.Update()
                    for s in sub.Sensors:
                        if s.SensorType == SensorType.Temperature and s.Value is not None:
                            return float(s.Value)
        if not _temp_debug_done:
            print("[TEMP DBG] No CPU hardware found in LHM!")
            print(f"[TEMP DBG] Total hardware items: {sum(1 for _ in _lhm_computer.Hardware)}")
            for hw in _lhm_computer.Hardware:
                print(f"[TEMP DBG]   {hw.Name} type={hw.HardwareType}")
        return -1.0
    except Exception as e:
        if not _temp_debug_done: print(f"[TEMP DBG] get_cpu_temp exception: {e}")
        return -1.0

def get_gpu_temp():
    global _temp_debug_done
    if not _lhm_available or _lhm_computer is None: return -1.0
    try:
        from LibreHardwareMonitor.Hardware import HardwareType, SensorType
        gpu_types = [HardwareType.GpuNvidia, HardwareType.GpuAmd, HardwareType.GpuIntel]
        for hw in _lhm_computer.Hardware:
            if hw.HardwareType in gpu_types:
                hw.Update(); best = None
                if not _temp_debug_done:
                    print(f"[TEMP DBG] GPU hw found: {hw.Name} type={hw.HardwareType}")
                    for s in hw.Sensors:
                        val_s = f"{s.Value:.1f}" if s.Value is not None else "None"
                        print(f"[TEMP DBG]   {s.Name} type={s.SensorType} val={val_s}")
                for s in hw.Sensors:
                    if s.SensorType == SensorType.Temperature and s.Value is not None:
                        n = s.Name.lower()
                        if "core" in n or "gpu" in n or "temperature" in n: return float(s.Value)
                        if best is None: best = float(s.Value)
                if best is not None: return best
        if not _temp_debug_done:
            print("[TEMP DBG] No GPU hardware matched gpu_types!")
        _temp_debug_done = True
        return -1.0
    except Exception as e:
        if not _temp_debug_done: print(f"[TEMP DBG] get_gpu_temp exception: {e}")
        _temp_debug_done = True
        return -1.0

def get_gpu_vram_total_mb(log_fn=print):
    """Get total GPU VRAM in MB. Tries LHM first, then nvidia-smi."""
    # Method 1: LibreHardwareMonitor
    if _lhm_available and _lhm_computer is not None:
        try:
            from LibreHardwareMonitor.Hardware import HardwareType, SensorType
            gpu_types = [HardwareType.GpuNvidia, HardwareType.GpuAmd, HardwareType.GpuIntel]
            found_gpu = False
            for hw in _lhm_computer.Hardware:
                if hw.HardwareType in gpu_types:
                    found_gpu = True
                    hw.Update()
                    log_fn(f"[VRAM] GPU found: {hw.Name} ({hw.HardwareType})")
                    for s in hw.Sensors:
                        val_s = f"{s.Value:.1f}" if s.Value is not None else "None"
                        log_fn(f"[VRAM]   {s.Name}  Type={s.SensorType}  Val={val_s}")
                        if s.Value is not None and s.Value > 0:
                            n = s.Name.lower()
                            if s.SensorType == SensorType.SmallData and "total" in n and "memory" in n:
                                val = int(s.Value)
                                log_fn(f"[VRAM] MATCH (SmallData): {s.Name} = {val} MB")
                                return val
                            if s.SensorType == SensorType.Data and "total" in n and "memory" in n:
                                val = int(s.Value * 1024)
                                log_fn(f"[VRAM] MATCH (Data): {s.Name} = {val} MB")
                                return val
                    log_fn("[VRAM] No 'total memory' sensor matched on this GPU")
            if not found_gpu:
                log_fn("[VRAM] LHM has no GPU hardware entries")
        except Exception as e:
            log_fn(f"[WARN] LHM VRAM total failed: {e}")
    else:
        log_fn("[VRAM] LHM not available, skipping")
    # Method 2: nvidia-smi
    try:
        out = subprocess.check_output(
            ["nvidia-smi", "--query-gpu=memory.total", "--format=csv,noheader,nounits"],
            timeout=5, stderr=subprocess.DEVNULL,
            creationflags=_NO_WINDOW).decode().strip()
        val = int(out.split("\n")[0].strip())
        if val > 0:
            log_fn(f"[VRAM] nvidia-smi total: {val} MB")
            return val
    except FileNotFoundError:
        log_fn("[VRAM] nvidia-smi not found (no NVIDIA GPU?)")
    except Exception as e:
        log_fn(f"[VRAM] nvidia-smi failed: {e}")
    # Method 3: Windows Registry (handles >4GB correctly, 64-bit QWORD)
    try:
        import winreg
        base = r"SYSTEM\ControlSet001\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}"
        i = 0
        while True:
            try:
                subkey = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, f"{base}\\{i:04d}")
                try:
                    val, _ = winreg.QueryValueEx(subkey, "HardwareInformation.qwMemorySize")
                    if val and val > 0:
                        val_mb = int(val) // (1024 * 1024)
                        log_fn(f"[VRAM] Registry qwMemorySize: {val_mb} MB")
                        if val_mb > 0:
                            return val_mb
                except FileNotFoundError:
                    pass
                winreg.CloseKey(subkey)
                i += 1
            except OSError:
                break
        log_fn("[VRAM] Registry: no qwMemorySize found")
    except Exception as e:
        log_fn(f"[VRAM] Registry failed: {e}")
    # Method 4: WMI fallback (caps at 4GB for >4GB GPUs)
    try:
        out = subprocess.check_output(
            ["wmic", "path", "Win32_VideoController", "get", "AdapterRAM", "/value"],
            timeout=5, stderr=subprocess.DEVNULL,
            creationflags=_NO_WINDOW).decode().strip()
        log_fn(f"[VRAM] WMI raw output: {out!r}")
        for line in out.splitlines():
            if "AdapterRAM=" in line:
                val_bytes = int(line.split("=")[1].strip())
                if val_bytes > 0:
                    val_mb = val_bytes // (1024 * 1024)
                    if val_mb >= 4095:
                        log_fn(f"[VRAM] WMI: {val_mb} MB (likely capped at 4GB -- real value may be higher)")
                    else:
                        log_fn(f"[VRAM] WMI total: {val_mb} MB")
                    return val_mb
    except Exception as e:
        log_fn(f"[VRAM] WMI failed: {e}")
    log_fn("[WARN] Could not detect total VRAM")
    return -1

def get_link_speed_mbps():
    try:
        stats = psutil.net_if_stats(); addrs = psutil.net_if_addrs(); best = 0
        for name, st in stats.items():
            if not st.isup or st.speed == 0: continue
            nl = name.lower()
            if "loopback" in nl or nl == "lo": continue
            if name in addrs:
                has_ip = any(a.family.name == 'AF_INET' and not a.address.startswith('169.254')
                             for a in addrs[name])
                if has_ip and st.speed > best: best = st.speed
        if best == 0:
            for name, st in stats.items():
                if st.isup and st.speed > best: best = st.speed
        return best if best > 0 else 1000
    except Exception: return 1000

class NetSpeed:
    def __init__(self):
        c = psutil.net_io_counters()
        self.prev_recv = c.bytes_recv; self.prev_sent = c.bytes_sent
        self.prev_time = time.time()
    def update(self):
        c = psutil.net_io_counters(); now = time.time(); dt = now - self.prev_time
        if dt <= 0: return 0, 0
        dl = (c.bytes_recv - self.prev_recv) / dt / 1024.0
        ul = (c.bytes_sent - self.prev_sent) / dt / 1024.0
        self.prev_recv = c.bytes_recv; self.prev_sent = c.bytes_sent; self.prev_time = now
        return int(round(dl)), int(round(ul))

def _parse_typeperf_csv(out):
    """Return [(counter_path, value)] from a one-sample `typeperf` CSV dump."""
    import csv
    rows = [r for r in csv.reader(io.StringIO(out)) if r]
    header = next((r for r in rows if len(r) > 1 and r[1].startswith("\\\\")), None)
    if header is None:
        return []
    values = next((r for r in rows[rows.index(header) + 1:] if len(r) == len(header)), None)
    if values is None:
        return []
    pairs = []
    for path, raw in zip(header[1:], values[1:]):
        try:
            pairs.append((path, float(raw)))
        except ValueError:
            pass
    return pairs

def _gpu_from_lhm():
    """(load %, VRAM used MB) straight from LibreHardwareMonitor, -1 when unknown.

    LHM reads the driver's own "GPU Core" load and "GPU Memory Used" sensors, which
    match what NVIDIA/AMD tools report, so it is preferred over perf counters.
    """
    if not _lhm_available or _lhm_computer is None:
        return -1.0, -1
    try:
        from LibreHardwareMonitor.Hardware import HardwareType, SensorType
        gpu_types = [HardwareType.GpuNvidia, HardwareType.GpuAmd, HardwareType.GpuIntel]
        for hw in _lhm_computer.Hardware:
            if hw.HardwareType not in gpu_types:
                continue
            hw.Update()
            load, used = -1.0, -1
            for s in hw.Sensors:
                if s.Value is None:
                    continue
                n = s.Name.lower()
                if s.SensorType == SensorType.Load and n in ("gpu core", "d3d 3d") and load < 0:
                    load = float(s.Value)
                elif s.SensorType == SensorType.SmallData and "memory used" in n and "shared" not in n:
                    used = int(s.Value)
            if load >= 0 or used >= 0:
                return load, used
    except Exception:
        pass
    return -1.0, -1

def get_gpu_counters():
    """(GPU load %, dedicated VRAM used MB) from ONE typeperf call.

    The old code ran typeperf twice per frame (~1 s each). Load follows Task
    Manager: sum the engines of each engine type (3D, Copy, VideoDecode, ...)
    and report the busiest type, instead of adding every engine together.
    """
    global _vram_failures
    lhm_load, lhm_used = _gpu_from_lhm()
    if lhm_load >= 0 and lhm_used >= 0:
        return min(lhm_load, 100.0), lhm_used
    counters = ["\\GPU Engine(*)\\Utilization Percentage"]
    if _vram_failures < _VRAM_MAX_FAIL and lhm_used < 0:
        counters.append("\\GPU Process Memory(*)\\Dedicated Usage")
    try:
        out = subprocess.check_output(["typeperf", *counters, "-sc", "1"], timeout=6,
                                      stderr=subprocess.DEVNULL,
                                      creationflags=_NO_WINDOW).decode(errors="ignore")
    except Exception:
        return (lhm_load if lhm_load >= 0 else 0.0), lhm_used
    per_type, vram_bytes, saw_vram = {}, 0.0, False
    for path, val in _parse_typeperf_csv(out):
        p = path.lower()
        if "gpu engine" in p:
            m = re.search(r"engtype_([a-z0-9 ]+)", p)
            key = m.group(1) if m else "all"
            per_type[key] = per_type.get(key, 0.0) + val
        elif "dedicated usage" in p:
            vram_bytes += val; saw_vram = True
    load = lhm_load if lhm_load >= 0 else min(max(per_type.values(), default=0.0), 100.0)
    used = lhm_used
    if used < 0 and len(counters) > 1:
        if saw_vram and vram_bytes > 0:
            used = int(vram_bytes / (1024 * 1024)); _vram_failures = 0
        else:
            _vram_failures += 1
    return load, used

def wait_for_ready(ser, timeout_s=3.0, log_fn=print, lcd_fn=None, stop_event=None):
    log_fn("Waiting for MCU READY...")
    end = time.time() + timeout_s
    while time.time() < end:
        if stop_event is not None and stop_event.is_set():
            return False
        line = ser.readline().decode(errors="ignore").strip()
        if line:
            log_fn(f"RX: {line}")
            # Detect LCD discovery reports  (FOUND_LCD=0x27)
            if lcd_fn:
                m = re.search(r"FOUND_LCD=0x([0-9A-Fa-f]+)", line, re.IGNORECASE)
                if m:
                    lcd_fn("0x" + m.group(1).upper())
            if "READY" in line:
                return True
    return False


# ══════════════════════════════════════════════════════════════════════════════
#  MONITOR THREAD
# ══════════════════════════════════════════════════════════════════════════════

RECONNECT_DELAY_S = 3

class MonitorThread(threading.Thread):
    """Samples the sensors and streams one frame per second to the board.

    Reports its state on status_q as (state, detail) where state is one of
    connecting / waiting / running / reconnecting / error / stopped. When the
    board is unplugged or the port vanishes it keeps retrying (auto_reconnect)
    and keeps sampling, so the dashboard stays live while the board is away.
    `flags` is a dict shared with the GUI: verbose (log raw frames) and ident.
    """
    def __init__(self, cfg, log_q, stats_q, lcd_q, stop_event, status_q=None, flags=None):
        super().__init__(daemon=True)
        self.cfg        = cfg
        self.log_q      = log_q
        self.stats_q    = stats_q
        self.lcd_q      = lcd_q        # ← queue for discovered LCD addresses
        self.stop_event = stop_event
        self.status_q   = status_q or queue.Queue()
        self.flags      = flags if flags is not None else {}

    def log(self, msg): self.log_q.put(msg)

    def status(self, state, detail=""):
        self.status_q.put((state, detail))

    def _on_lcd_found(self, addr_str):
        """Called when Arduino reports a discovered LCD during boot."""
        self.lcd_q.put(addr_str)

    def _rx(self, line):
        self.log(f"RX: {line}")
        m = re.search(r"FOUND_LCD=0x([0-9A-Fa-f]+)", line, re.IGNORECASE)
        if m: self._on_lcd_found("0x" + m.group(1).upper())

    def _setup(self):
        cfg = self.cfg
        global _lhm_computer, _lhm_available, _lhm_init_tried
        _lhm_computer = None; _lhm_available = False; _lhm_init_tried = False
        dll = _ensure_lhm_deps(cfg["lhm_path"], self.log)
        if os.path.isfile(dll):
            self.log(f"[INFO] LHM DLL found: {dll}")
        else:
            self.log(f"[WARN] LHM DLL not found: {dll}")
            self.log("[WARN] CPU/GPU temperatures will show as N/A")
        _init_lhm(dll, self.log)
        if _lhm_available:
            self.log("[OK]   LibreHardwareMonitor ready -- temperatures enabled")
        else:
            self.log("[WARN] Temperatures disabled (LHM unavailable)")

        # page_order is a list like [0,2,1,3] (indices: CPU=0 GPU=1 RAM=2 NET=3)
        self.page_order = cfg.get("page_order", [0, 1, 2, 3]) or [0]
        if not cfg.get("page_order"):
            self.log("[WARN] No pages -- enabling CPU fallback.")
        self.mask = sum(1 << i for i in self.page_order)
        names = ["CPU", "GPU", "RAM", "NET"]
        self.log(f"[INFO] Page order: {' -> '.join(names[i] for i in self.page_order)}"
                 f"  |  Delay: {cfg['page_delay']} ms")

        raw_mb    = int(psutil.virtual_memory().total / (1024 * 1024))
        common_gb = [4,8,12,16,24,32,48,64,96,128,256]
        ram_gb    = min((g for g in common_gb if g >= raw_mb/1024.0), default=common_gb[-1])
        self.ram_total = ram_gb * 1024
        self.log(f"[INFO] RAM: {raw_mb} MB  ->  {ram_gb} GB")
        self.vram_total = get_gpu_vram_total_mb(self.log)
        self.link_speed = get_link_speed_mbps()
        self.log(f"[INFO] NIC link: {self.link_speed} Mbps")
        psutil.cpu_percent(interval=None)
        self.net = NetSpeed()

    def _sample(self):
        cpu = psutil.cpu_percent(interval=0.0)
        mem = psutil.virtual_memory()
        gpu, vram_mb = get_gpu_counters()
        dl_kb, ul_kb = self.net.update()
        s = {
            "cpu": cpu, "cpu_temp": get_cpu_temp(),
            "gpu": gpu, "gpu_temp": get_gpu_temp(),
            "ram": mem.percent, "ram_mb": int(mem.used / (1024 * 1024)),
            "ram_total_mb": self.ram_total,
            "vram_mb": vram_mb, "vram_total_mb": self.vram_total,
            "dl_kb": dl_kb, "ul_kb": ul_kb, "link_speed": self.link_speed,
        }
        self.stats_q.put(s)
        return s

    def _frame(self, s):
        cfg = self.cfg
        t10 = lambda v: int(round(v * 10)) if v >= 0 else -1
        lt = cfg.get("lcd_types", {})
        big = [str(int(a, 16)) for a, t in lt.items() if t == "2004"]
        parts = [
            f"CPU={t10(s['cpu'])};RAM={t10(s['ram'])};GPU={t10(s['gpu'])}",
            f"DL={s['dl_kb']};UL={s['ul_kb']}",
            f"RAMU={s['ram_mb']};RAMT={int(self.ram_total)};VRAM={s['vram_mb']};VRAMT={self.vram_total}",
            f"TEMP={t10(s['cpu_temp'])};GPUT={t10(s['gpu_temp'])}",
            f"LSPD={self.link_speed};PG={self.mask};PDLY={cfg['page_delay']};"
            f"PGORD={','.join(str(i) for i in self.page_order)}",
        ]
        if big:
            parts.append(f"LCD2004={','.join(big)}")
        return ";".join(parts) + "\r\n"

    def _session(self):
        """One connection: open, wait for READY, stream until stopped or the port dies."""
        import serial as ser_mod
        cfg = self.cfg
        self.status("connecting", cfg["port"])
        with ser_mod.Serial(cfg["port"], cfg["baud"], timeout=0.2) as ser:
            try: ser.dtr = False; ser.rts = False
            except Exception: pass
            time.sleep(0.2)
            ser.reset_input_buffer(); ser.reset_output_buffer()
            self.status("waiting", cfg["port"])
            if not wait_for_ready(ser, 8.0, self.log, self._on_lcd_found, self.stop_event):
                if self.stop_event.is_set():
                    return
                self.log("[INFO] No READY seen -- continuing anyway.")
            self.log(f"[OK] Connected to {cfg['port']} @ {cfg['baud']} baud")
            self.status("running", cfg["port"])
            frames = 0
            while not self.stop_event.is_set():
                started = time.time()
                s = self._sample()
                line = self._frame(s)
                ser.write(line.encode("ascii")); ser.flush()
                frames += 1
                if self.flags.get("verbose"):
                    self.log(f"[DBG] TX {line.strip()}")
                elif frames == 1:
                    self.log("[OK] Streaming stats (enable 'Show raw serial traffic' in the Log tab to see frames)")
                if self.flags.pop("ident", False):
                    ser.write(b"IDENT\r\n"); ser.flush()
                    self.log("[INFO] IDENT sent -- each screen shows its number")
                # Read board replies until the next frame is due (~1 frame/second).
                while not self.stop_event.is_set() and time.time() - started < 1.0:
                    if ser.in_waiting:
                        rx = ser.readline().decode(errors="ignore").strip()
                        if rx and (self.flags.get("verbose") or rx not in ("OK",) and not rx.startswith("[DBG]")):
                            self._rx(rx)
                    else:
                        time.sleep(0.05)

    def run(self):
        cfg = self.cfg
        self.log("─" * 55)
        self.log("[INFO] PC Monitor starting up...")
        self.log(f"[INFO] Port: {cfg['port']}  Baud: {cfg['baud']}")
        if not PSUTIL_OK:
            self.log("[ERROR] psutil not installed.  pip install psutil")
            self.status("error", "psutil missing"); return
        if not SERIAL_OK:
            self.log("[ERROR] pyserial not installed.  pip install pyserial")
            self.status("error", "pyserial missing"); return
        self.status("connecting", cfg["port"])
        try:
            self._setup()
        except Exception as e:
            import traceback
            self.log(f"[ERROR] Sensor setup failed: {e}")
            self.log(traceback.format_exc())
            self.status("error", str(e)); return

        import serial as ser_mod
        while not self.stop_event.is_set():
            try:
                self._session()
            except (ser_mod.SerialException, OSError) as e:
                self.log(f"[ERROR] Serial: {e}")
                if not cfg.get("auto_reconnect", True):
                    self.status("error", str(e)); break
                self.status("reconnecting", cfg["port"])
                self.log(f"[INFO] Retrying {cfg['port']} every {RECONNECT_DELAY_S} s "
                         "(plug the board back in, or press Stop)")
                # keep the dashboard alive while the board is away
                while not self.stop_event.wait(RECONNECT_DELAY_S):
                    try:
                        self._sample()
                        import serial.tools.list_ports as lp
                        if any(p.device == cfg["port"] for p in lp.comports()):
                            break
                    except Exception:
                        break
            except Exception as e:
                import traceback
                self.log(f"[ERROR] {e}")
                self.log(traceback.format_exc())
                self.status("error", str(e)); break
        else:
            self.status("stopped")
        self.log("[INFO] Monitor stopped.")
        if self.stop_event.is_set():
            self.status("stopped")


# ══════════════════════════════════════════════════════════════════════════════
#  LCD PREVIEW MODEL -- mirrors the Arduino firmware's page layout
# ══════════════════════════════════════════════════════════════════════════════
# Bar cells are encoded as "\x01" (filled) / "\x02" (empty) inside row strings;
# LCDPreview draws them as blocks. "°" is the degree glyph.
_BAR_ON, _BAR_OFF = "\x01", "\x02"
PAGE_NAMES = ["CPU", "GPU", "RAM", "NET"]

def _bar(width, permille):
    filled = max(0, min(width, permille * width // 1000))
    return _BAR_ON * filled + _BAR_OFF * (width - filled)

def _pct4(v10):  return f"{max(0, v10) // 10:3d}%"
def _temp_dec(t10):  return " --.-" if t10 < 0 else f"{t10 // 10:2d}.{t10 % 10}°C"
def _temp_int(t10):  return " -- " if t10 < 0 else f"{t10 // 10:2d}°C"

def _mem_ratio(used, total):
    if total >= 1024:
        return f"{used // 1024}.{(used % 1024) * 10 // 1024}/{total // 1024}G"
    return f"{used}/{total}M"

def _vram_ratio(used, total):
    ug, tg = used // 1024, total // 1024
    if tg >= 10: return f"{ug}/{tg}G"
    if tg > 0:   return f"{ug}.{(used % 1024) * 10 // 1024}/{tg}G"
    return f"{used}/{total}M"

def _speed5(kb):
    kb = max(0, kb)
    if kb >= 10000: return f"{kb // 1024:4d}M"
    if kb >= 1000:
        m = kb * 10 // 1024
        return f"{m // 10}.{m % 10}M"
    return f"{kb:4d}K"

def _frame_values(s):
    """The integer values the firmware receives for stats dict `s`."""
    t10 = lambda v: int(round(v * 10)) if v is not None and v >= 0 else -1
    return {
        "cpu": t10(s.get("cpu", 0)), "ram": t10(s.get("ram", 0)), "gpu": t10(s.get("gpu", 0)),
        "temp": t10(s.get("cpu_temp", -1)), "gput": t10(s.get("gpu_temp", -1)),
        "ramu": int(s.get("ram_mb", 0)), "ramt": int(s.get("ram_total_mb", 0)),
        "vram": int(s.get("vram_mb", -1)), "vramt": int(s.get("vram_total_mb", -1)),
        "dl": int(s.get("dl_kb", 0)), "ul": int(s.get("ul_kb", 0)),
        "lspd": int(s.get("link_speed", 1000)) or 1000,
    }

def _net_permille(kb, lspd):
    return max(0, min(1000, kb * 1000 // (lspd * 125)))

def render_1602(page, s):
    """Two 16-char rows, same as show1602Page() in Arduino-PC-Monitor-1602."""
    v = _frame_values(s)
    if page == 0:
        top = f"CPU {_pct4(v['cpu'])}  {_temp_dec(v['temp'])}"; bar = _bar(16, v["cpu"])
    elif page == 1:
        if v["gput"] % 10:          # firmware: (gput10 % 10 != 0), true for -1 (no sensor) too
            top = f"GPU {_pct4(v['gpu'])}  {_temp_dec(v['gput'])}"
        elif v["vramt"] >= 10240:
            top = f"GPU {_pct4(v['gpu'])}   {_temp_int(v['gput'])} "
        else:
            vr = _vram_ratio(max(v["vram"], 0), v["vramt"]) if v["vramt"] > 0 else " -- "
            top = f"GPU {vr:<6s}  {_temp_int(v['gput'])}"
        bar = _bar(16, v["gpu"])
    elif page == 2:
        top = f"RAM{_pct4(v['ram'])} {_mem_ratio(v['ramu'], v['ramt'])}"; bar = _bar(16, v["ram"])
    else:
        top = f"DL:{_speed5(v['dl'])} UL:{_speed5(v['ul'])}"
        bar = _bar(8, _net_permille(v["dl"], v["lspd"])) + _bar(8, _net_permille(v["ul"], v["lspd"]))
    return [top[:16].ljust(16), bar]

def _compose(left, mid, right, cols=20):
    row = [" "] * cols
    row[:len(left)] = left[:cols]
    if len(right) <= cols:
        row[cols - len(right):] = right
    if mid:
        gs, ge = len(left) + 1, (cols - len(right) - 1 if len(right) + 1 <= cols else 0)
        if gs < ge and len(mid) <= ge - gs:
            st = gs + (ge - gs - len(mid)) // 2
            row[st:st + len(mid)] = mid
    return "".join(row[:cols])

def render_2004_block(page, s):
    """One metric block (label row + bar row), same as renderBlock() in the 2004 firmware."""
    v = _frame_values(s)
    if page == 0:
        return [_compose(f"CPU {_pct4(v['cpu'])}", "", _temp_dec(v["temp"])), _bar(20, v["cpu"])]
    if page == 1:
        t = _temp_dec(v["gput"]) if v["gput"] >= 0 and v["gput"] % 10 else _temp_int(v["gput"])
        vr = _vram_ratio(max(v["vram"], 0), v["vramt"]) if v["vramt"] > 0 else ""
        return [_compose(f"GPU {_pct4(v['gpu'])}", vr, t), _bar(20, v["gpu"])]
    if page == 2:
        return [_compose(f"RAM {_pct4(v['ram'])}", "", _mem_ratio(v["ramu"], v["ramt"])), _bar(20, v["ram"])]
    return [_compose(f"DL{_speed5(v['dl'])}", "", f"UL{_speed5(v['ul'])}"),
            _bar(10, _net_permille(v["dl"], v["lspd"])) + _bar(10, _net_permille(v["ul"], v["lspd"]))]

def distribute_pages(n_lcds, pages):
    """Which pages each screen cycles through -- distributePages() in the firmware:
    one page per screen, and the last screen rotates through whatever is left."""
    if n_lcds <= 0 or not pages:
        return []
    if len(pages) <= n_lcds:
        return [[p] for p in pages] + [[] for _ in range(n_lcds - len(pages))]
    fixed = n_lcds - 1
    return [[p] for p in pages[:fixed]] + [pages[fixed:]]

def screen_rows(kind, pages, step, s):
    """Rows a screen of `kind` ("1602"/"2004") shows at rotation `step`."""
    if not pages:
        return [""] * (2 if kind == "1602" else 4)
    if kind == "1602":
        return render_1602(pages[step % len(pages)], s)
    views = (len(pages) + 1) // 2
    top = (step % views) * 2
    rows = render_2004_block(pages[top], s)
    rows += render_2004_block(pages[top + 1], s) if top + 1 < len(pages) else [" " * 20] * 2
    return rows


# ══════════════════════════════════════════════════════════════════════════════
#  REUSABLE WIDGETS
# ══════════════════════════════════════════════════════════════════════════════
UI_FONT, MONO_FONT = "Segoe UI", "Consolas"
MAX_LOG_LINES = 2000
HISTORY_LEN = 90   # samples kept for sparklines (~1.5 min at 1 frame/s)

def _level_color(pct, warn=60, hot=85):
    return GREEN if pct < warn else (YELLOW if pct < hot else RED)

def _temp_color(t):
    return TEXT_DIM if t is None or t < 0 else (GREEN if t < 65 else (YELLOW if t < 80 else RED))

def _fmt_rate(kb):
    if kb >= 1024 * 1024: return f"{kb / 1024 / 1024:.2f} GB/s"
    if kb >= 1024:        return f"{kb / 1024:.1f} MB/s"
    return f"{kb:.0f} KB/s"


class FlatButton(tk.Label):
    """A flat, hover-aware button (tk.Button ignores bg colours on some themes)."""
    def __init__(self, parent, text, command, bg=BG3, fg=TEXT, hover=None,
                 font=(UI_FONT, 9), padx=12, pady=5, **kw):
        super().__init__(parent, text=text, bg=bg, fg=fg, font=font, padx=padx,
                         pady=pady, cursor="hand2", **kw)
        self._bg, self._hover, self._cmd, self._enabled = bg, hover or BORDER, command, True
        self.bind("<Enter>", lambda e: self._enabled and super(FlatButton, self).config(bg=self._hover))
        self.bind("<Leave>", lambda e: super(FlatButton, self).config(bg=self._bg))
        self.bind("<ButtonRelease-1>", self._click)

    def _click(self, e):
        if self._enabled and self._cmd and 0 <= e.x <= self.winfo_width() and 0 <= e.y <= self.winfo_height():
            self._cmd()

    def style(self, text=None, bg=None, fg=None, hover=None, enabled=None):
        if bg is not None: self._bg = bg
        if hover is not None: self._hover = hover
        if enabled is not None:
            self._enabled = enabled
            self.config(cursor="hand2" if enabled else "arrow")
        kw = {"bg": self._bg}
        if text is not None: kw["text"] = text
        if fg is not None: kw["fg"] = fg
        super().config(**kw)


class Card(tk.Frame):
    """Rounded-feeling panel: title row + body frame."""
    def __init__(self, parent, title="", subtitle="", **kw):
        super().__init__(parent, bg=BG2, highlightbackground=BORDER, highlightthickness=1, **kw)
        self.header = tk.Frame(self, bg=BG2)
        self.header.pack(fill="x", padx=14, pady=(10, 4))
        if title:
            tk.Label(self.header, text=title, bg=BG2, fg=TEXT,
                     font=(UI_FONT, 10, "bold")).pack(side="left")
        if subtitle:
            tk.Label(self.header, text=subtitle, bg=BG2, fg=TEXT_DIM,
                     font=(UI_FONT, 8)).pack(side="left", padx=(8, 0), pady=(2, 0))
        self.body = tk.Frame(self, bg=BG2)
        self.body.pack(fill="both", expand=True, padx=14, pady=(0, 12))


class Sparkline(tk.Canvas):
    """Filled line chart of recent samples. Series values are 0..100 unless
    autoscale is set (then scaled to the largest visible value)."""
    def __init__(self, parent, colors=(ACCENT,), height=46, autoscale=False, **kw):
        super().__init__(parent, bg=BG2, height=height, highlightthickness=0, **kw)
        self.colors, self.autoscale = colors, autoscale
        self.series = [[] for _ in colors]
        self.bind("<Configure>", lambda e: self.redraw())

    def push(self, *values):
        for i, v in enumerate(values):
            self.series[i].append(max(0.0, float(v)))
            del self.series[i][:-HISTORY_LEN]
        self.redraw()

    def redraw(self):
        self.delete("all")
        w, h = self.winfo_width(), self.winfo_height()
        if w < 10 or h < 10:
            return
        for frac in (0.5,):
            self.create_line(0, h * frac, w, h * frac, fill=BG3, dash=(2, 4))
        top = 100.0
        if self.autoscale:
            top = max([1.0] + [v for s in self.series for v in s]) * 1.15
        step = w / (HISTORY_LEN - 1)
        for color, data in zip(self.colors, self.series):
            if len(data) < 2:
                continue
            x0 = w - step * (len(data) - 1)
            pts = []
            for i, v in enumerate(data):
                pts += [x0 + i * step, h - 2 - (h - 4) * min(v, top) / top]
            if len(self.colors) == 1:
                self.create_polygon(pts[0], h, *pts, pts[-2], h, fill=_blend(color, BG2, 0.22), outline="")
            self.create_line(*pts, fill=color, width=2, smooth=True)


def _blend(c1, c2, a):
    """Mix colour c1 into c2 by alpha a (Tk has no alpha)."""
    r1, g1, b1 = (int(c1[i:i + 2], 16) for i in (1, 3, 5))
    r2, g2, b2 = (int(c2[i:i + 2], 16) for i in (1, 3, 5))
    return "#%02x%02x%02x" % (int(r2 + (r1 - r2) * a), int(g2 + (g1 - g2) * a), int(b2 + (b1 - b2) * a))


class UsageBar(tk.Canvas):
    def __init__(self, parent, height=8, **kw):
        super().__init__(parent, bg=BG3, height=height, highlightthickness=0, **kw)
        self._pct, self._color = 0.0, GREEN
        self.bind("<Configure>", lambda e: self._draw())

    def set(self, pct, color=None):
        self._pct, self._color = max(0.0, min(100.0, pct)), color or _level_color(pct)
        self._draw()

    def _draw(self):
        self.delete("all")
        w, h = self.winfo_width(), self.winfo_height()
        if self._pct > 0:
            self.create_rectangle(0, 0, max(2, w * self._pct / 100), h, fill=self._color, outline="")


class MetricCard(tk.Frame):
    """Big-number tile: name, value, temperature chip, detail line, bar, sparkline."""
    def __init__(self, parent, name, color, **kw):
        super().__init__(parent, bg=BG2, highlightbackground=BORDER, highlightthickness=1, **kw)
        self.color = color
        top = tk.Frame(self, bg=BG2); top.pack(fill="x", padx=14, pady=(10, 0))
        tk.Label(top, text="●", bg=BG2, fg=color, font=(UI_FONT, 9)).pack(side="left")
        tk.Label(top, text=f" {name}", bg=BG2, fg=TEXT_DIM, font=(UI_FONT, 9, "bold")).pack(side="left")
        self.temp = tk.Label(top, text="", bg=BG2, fg=TEXT_DIM, font=(UI_FONT, 10, "bold"))
        self.temp.pack(side="right")
        self.value = tk.Label(self, text="--", bg=BG2, fg=TEXT, font=(UI_FONT, 26, "bold"), anchor="w")
        self.value.pack(fill="x", padx=12)
        self.detail = tk.Label(self, text=" ", bg=BG2, fg=TEXT_DIM, font=(UI_FONT, 9), anchor="w")
        self.detail.pack(fill="x", padx=14)
        self.bar = UsageBar(self); self.bar.pack(fill="x", padx=14, pady=(6, 4))
        self.spark = Sparkline(self, colors=(color,)); self.spark.pack(fill="both", expand=True, padx=8, pady=(0, 8))

    def update_values(self, pct, value_text, detail="", temp=None):
        self.value.config(text=value_text)
        self.detail.config(text=detail or " ")
        self.bar.set(pct)
        self.spark.push(pct)
        if temp is None or temp < 0:
            self.temp.config(text="", fg=TEXT_DIM)
        else:
            self.temp.config(text=f"{temp:.0f}°C", fg=_temp_color(temp))


class NetCard(tk.Frame):
    def __init__(self, parent, **kw):
        super().__init__(parent, bg=BG2, highlightbackground=BORDER, highlightthickness=1, **kw)
        top = tk.Frame(self, bg=BG2); top.pack(fill="x", padx=14, pady=(10, 0))
        tk.Label(top, text="●", bg=BG2, fg=YELLOW, font=(UI_FONT, 9)).pack(side="left")
        tk.Label(top, text=" NETWORK", bg=BG2, fg=TEXT_DIM, font=(UI_FONT, 9, "bold")).pack(side="left")
        self.link = tk.Label(top, text="", bg=BG2, fg=TEXT_DIM, font=(UI_FONT, 9))
        self.link.pack(side="right")
        vals = tk.Frame(self, bg=BG2); vals.pack(fill="x", padx=12)
        self.dl = tk.Label(vals, text="↓ --", bg=BG2, fg=TEXT, font=(UI_FONT, 18, "bold"))
        self.dl.pack(side="left")
        self.ul = tk.Label(vals, text="↑ --", bg=BG2, fg=ACCENT2, font=(UI_FONT, 18, "bold"))
        self.ul.pack(side="left", padx=(18, 0))
        self.detail = tk.Label(self, text="Download  ·  Upload", bg=BG2, fg=TEXT_DIM,
                               font=(UI_FONT, 9), anchor="w")
        self.detail.pack(fill="x", padx=14, pady=(2, 6))
        self.spark = Sparkline(self, colors=(YELLOW, ACCENT2), autoscale=True)
        self.spark.pack(fill="both", expand=True, padx=8, pady=(0, 8))

    def update_values(self, dl_kb, ul_kb, link):
        self.dl.config(text=f"↓ {_fmt_rate(dl_kb)}", fg=YELLOW)
        self.ul.config(text=f"↑ {_fmt_rate(ul_kb)}")
        self.link.config(text=f"{link} Mbps link" if link else "")
        self.spark.push(dl_kb, ul_kb)


class LCDPreview(tk.Canvas):
    """A character LCD drawn cell by cell (16x2 or 20x4), green-on-black."""
    CW, CH, GAP = 11, 17, 2

    def __init__(self, parent, cols=16, rows=2, **kw):
        self.cols, self.rows = cols, rows
        w = cols * (self.CW + self.GAP) + 22
        h = rows * (self.CH + self.GAP) + 18
        super().__init__(parent, width=w, height=h, bg=BG2, highlightthickness=0, **kw)
        self.create_rectangle(1, 1, w - 1, h - 1, fill=LCD_FRAME, outline=BORDER)
        self.create_rectangle(7, 6, w - 7, h - 6, fill=LCD_BG, outline="#1a2e1a")
        self._cells = []
        for r in range(rows):
            for c in range(cols):
                x = 11 + c * (self.CW + self.GAP)
                y = 9 + r * (self.CH + self.GAP)
                bg = self.create_rectangle(x, y, x + self.CW, y + self.CH, fill=LCD_DIM, outline="")
                tx = self.create_text(x + self.CW / 2, y + self.CH / 2, text="", fill=LCD_ON,
                                      font=(MONO_FONT, 10, "bold"))
                self._cells.append((bg, tx))
        self._last = None

    def set_rows(self, rows):
        rows = [(r + " " * self.cols)[:self.cols] for r in (rows + [""] * self.rows)[:self.rows]]
        if rows == self._last:
            return
        self._last = rows
        for r, line in enumerate(rows):
            for c, ch in enumerate(line):
                bg, tx = self._cells[r * self.cols + c]
                if ch == _BAR_ON:
                    self.itemconfig(bg, fill=LCD_ON); self.itemconfig(tx, text="")
                elif ch == _BAR_OFF:
                    self.itemconfig(bg, fill="#173d1f"); self.itemconfig(tx, text="")
                else:
                    self.itemconfig(bg, fill=LCD_DIM); self.itemconfig(tx, text=ch)


